package cn.zhuatech.dlp.service;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotBlank;import org.springframework.stereotype.Service;import java.util.*;
@Service public class DataPolicyExceptionService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.businessJustificationApproved())b.add("策略例外缺少批准的业务理由");if(!r.dataOwnerApproved())b.add("数据责任人未批准");if(r.restrictedData()&&!r.securityAndPrivacyApproved())b.add("受限数据未通过安全与隐私审批");if(!r.recipientVerified())b.add("接收方身份与用途未核验");if(r.expiryDays()>30)b.add("例外期限超过 30 天上限");if(!b.isEmpty()){a.add("拒绝例外并维持原 DLP 策略");return new Assessment(Decision.BLOCKED,b,a);}if(!r.encrypted()||!r.monitoringEnabled()||!r.revocationPlanReady()){if(!r.encrypted())a.add("启用端到端加密");if(!r.monitoringEnabled())a.add("启用下载与外发审计");if(!r.revocationPlanReady())a.add("配置到期自动撤销");return new Assessment(Decision.REVIEW,b,a);}a.add("批准限时例外并记录审批、用途和到期时间");return new Assessment(Decision.APPROVE,b,a);}public record Request(@NotBlank String exceptionId,boolean restrictedData,boolean businessJustificationApproved,boolean dataOwnerApproved,boolean securityAndPrivacyApproved,boolean recipientVerified,@Min(1)int expiryDays,boolean encrypted,boolean monitoringEnabled,boolean revocationPlanReady){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{APPROVE,REVIEW,BLOCKED}}
